        recs, headers = read_bed_file(i_file, tool_name="complement")
    else:
        recs, headers = read_bed_file(i_file, tool_name="complement")
    # Group recs by chrom, sort by start
    by_chrom=defaultdict(list)
    for r in recs:
        by_chrom[r["chrom"]].append(r)
    for chrom in by_chrom:
        by_chrom[chrom].sort(key=lambda x: (x["start"], x["end"]))
    # For each chrom in genome order? Or input order? Original complement outputs in genome file order? Let's test: genome has chr1, chr2; input has chr1 intervals; output is chr1 complements then chr2 full? Our earlier test gave chr1 complements then chr2. That matches genome order. What if genome has chr2 before chr1? Probably genome order. We'll use genome order.
    # If -L, limit to chroms with records? Else all chroms in genome.
    out=[]
    if L_flag:
        # Only chroms with records, in order of genome? Or input order? Let's use genome order filtered.
        chroms=[c for c in order if c in by_chrom]
        # What about chroms in input not in genome? Probably include? Bedtools complement ignores? Let's include them in input order? For now, include genome chroms plus extra.
        # Find extra chroms not in genome
        extra=[c for c in by_chrom if c not in genome]
        chroms.extend(extra)
    else:
        chroms=order[:]
        # Add extra chroms not in genome? Possibly at end? We'll add.
        for c in by_chrom:
            if c not in genome:
                chroms.append(c)
    for chrom in chroms:
        chrom_size=genome.get(chrom, None)
        intervals=by_chrom.get(chrom, [])
        # Merge intervals? Complement should consider union of intervals (merge overlapping) before complement? Yes, need to merge.
        # Sort and merge
        merged=[]
        for r in sorted(intervals, key=lambda x: (x["start"], x["end"])):
            s=max(0, r["start"])
            e=r["end"]
            if chrom_size is not None:
                e=min(e, chrom_size)
                # s already >=0
            if not merged:
                merged.append([s,e])
            else:
                if s <= merged[-1][1]:
                    if e > merged[-1][1]:
                        merged[-1][1]=e
                else:
                    merged.append([s,e])
        # Now complement
        prev=0
        if chrom_size is None:
            # No genome size for this chrom (extra)? Then what? Probably skip? Or use max end? For extra chroms, we don't know size, so skip? Let's just skip.
            continue
        for s,e in merged:
            if s > prev:
                out.append(f"{chrom}\t{prev}\t{s}")
            prev=max(prev, e)
        if prev < chrom_size:
            out.append(f"{chrom}\t{prev}\t{chrom_size}")
        # If no intervals, then whole chrom is complement (already handled: merged empty => prev=0 => output 0-chrom_size)
    sys.stdout.write("\n".join(out))
    if out:
        sys.stdout.write("\n")
