def cmd_merge(argv):
    if "-h" in argv or "--help" in argv:
        eprint(HELP.get("merge",""))
        sys.exit(1)
    i_file=None
    s_flag=False
    S_val=None
    d_val=0
    c_val=None
    o_val=None
    delim=","
    prec=5
    header=False
    p=0
    args=argv
    while p < len(args):
        tok=args[p]
        if tok=="-i":
            if p+1<len(args):
                i_file=args[p+1]
                p+=2
            else:
                p+=1
        elif tok=="-s":
            s_flag=True
            p+=1
        elif tok=="-S":
            if p+1<len(args):
                S_val=args[p+1]
                p+=2
            else:
                eprint(HELP.get("merge",""))
                eprint("\n\n***** ERROR: Unrecognized parameter: -S *****\n")
                sys.exit(1)
        elif tok=="-d":
            if p+1<len(args):
                try:
                    d_val=int(args[p+1])
                except:
                    try:
                        d_val=int(float(args[p+1]))
                    except:
                        d_val=0
                p+=2
            else:
                p+=1
        elif tok=="-c":
            if p+1<len(args):
                c_val=args[p+1]
                p+=2
            else:
                p+=1
        elif tok=="-o":
            if p+1<len(args):
                o_val=args[p+1]
                p+=2
            else:
                p+=1
        elif tok=="-delim":
            if p+1<len(args):
                delim=args[p+1]
                p+=2
            else:
                p+=1
        elif tok=="-prec":
            if p+1<len(args):
                try:
                    prec=int(args[p+1])
                except:
                    prec=5
                p+=2
            else:
                p+=1
        elif tok=="-header":
            header=True
            p+=1
        elif tok in ("-bed","-nobuf"):
            p+=1
        elif tok=="-iobuf":
            p+=2
        elif tok in ("-h","--help"):
            eprint(HELP.get("merge",""))
            sys.exit(1)
        elif tok.startswith("-"):
            eprint(HELP.get("merge",""))
            eprint(f"\n\n***** ERROR: Unrecognized parameter: {tok} *****\n")
            sys.exit(1)
        else:
            eprint(HELP.get("merge",""))
            eprint(f"\n\n***** ERROR: Unrecognized parameter: {tok} *****\n")
            sys.exit(1)
    if i_file is None:
        recs, headers = read_bed_file(None, tool_name="merge")
        i_file_for_err="stdin"
    else:
        if is_stdin_path(i_file):
            recs, headers = read_bed_file(i_file, tool_name="merge")
            i_file_for_err=i_file
        else:
            recs, headers = read_bed_file(i_file, tool_name="merge")
            i_file_for_err=i_file
    out_lines=[]
    if header:
        for h in headers:
            out_lines.append(h)
    if not recs:
        if out_lines:
            sys.stdout.write("\n".join(out_lines)+"\n")
        return
    prev_chrom=None
    prev_start=None
    for rec in recs:
        chrom=rec["chrom"]; start=rec["start"]
        if prev_chrom is not None:
            if chrom == prev_chrom:
                if start < prev_start:
                    eprint(f"Error: Sorted input specified, but the file {i_file_for_err} has the following out of order record\n{rec['line']}\n")
                    sys.exit(1)
            else:
                if chrom < prev_chrom:
                    eprint(f"Error: Sorted input specified, but the file {i_file_for_err} has the following out of order record\n{rec['line']}\n")
                    sys.exit(1)
        prev_chrom=chrom
        prev_start=start
    filtered_recs=[]
    if S_val is not None:
        if S_val not in ("+","-"):
            eprint(HELP.get("merge",""))
            eprint(f"\n\n***** ERROR: Unrecognized parameter: {S_val} *****\n")
            sys.exit(1)
        for rec in recs:
            if get_strand(rec)==S_val:
                filtered_recs.append(rec)
        recs=filtered_recs
        if not recs:
            if out_lines:
                sys.stdout.write("\n".join(out_lines)+"\n")
            return
    c_list=None
    o_list=None
    if c_val is not None:
        try:
            c_list=[int(x) for x in c_val.split(",")]
        except:
            c_list=None
    if o_val is not None:
        o_list=[x.strip() for x in o_val.split(",")]
    if c_list is not None and o_list is None:
        o_list=["sum"]*len(c_list)
    if o_list is not None and c_list is None:
        c_list=[5]*len(o_list)
    if c_list is not None and o_list is not None:
        if len(c_list)==1 and len(o_list)>1:
            c_list=c_list*len(o_list)
        elif len(o_list)==1 and len(c_list)>1:
            o_list=o_list*len(c_list)
        elif len(c_list)!=len(o_list):
            eprint(HELP.get("merge",""))
            eprint("\n\n***** ERROR: -c and -o must have same number of values or one must have single value. *****\n")
            sys.exit(1)
    merged=[]
    cur=None
    for rec in recs:
        if cur is None:
            cur={"chrom":rec["chrom"],"start":rec["start"],"end":rec["end"],"members":[rec]}
            continue
        same_chrom = (rec["chrom"]==cur["chrom"])
        strand_ok=True
        if s_flag:
            if get_strand(rec) != get_strand(cur["members"][0]):
                strand_ok=False
        dist = rec["start"] - cur["end"]
        if same_chrom and strand_ok and dist <= d_val:
            if rec["end"] > cur["end"]:
                cur["end"]=rec["end"]
            cur["members"].append(rec)
        else:
            merged.append(cur)
            cur={"chrom":rec["chrom"],"start":rec["start"],"end":rec["end"],"members":[rec]}
    if cur is not None:
        merged.append(cur)
    for m in merged:
        base=[m["chrom"], str(m["start"]), str(m["end"])]
        if c_list is not None and o_list is not None:
            for col, op in zip(c_list, o_list):
                vals=[]
                for mem in m["members"]:
                    fields=mem["fields"]
                    if col-1 < len(fields):
                        vals.append(fields[col-1])
                    else:
                        vals.append("")
                res=apply_merge_op(vals, op, delim, prec)
                base.append(res)
        out_lines.append("\t".join(base))
    sys.stdout.write("\n".join(out_lines))
    if out_lines:
        sys.stdout.write("\n")

def apply_merge_op(vals, op, delim=",", prec=5):
    op=op.strip()
    if op=="collapse":
        return delim.join(vals)
    elif op=="distinct":
        seen=set()
        uniq=[]
        for v in vals:
            if v not in seen:
                seen.add(v)
                uniq.append(v)
        return delim.join(uniq)
    elif op=="distinct_sort_num":
        try:
            uniq_sorted=sorted(set(vals), key=lambda x: float(x))
        except:
            uniq_sorted=sorted(set(vals))
        return delim.join(uniq_sorted)
    elif op=="distinct_sort_num_desc":
        try:
            uniq_sorted=sorted(set(vals), key=lambda x: float(x), reverse=True)
        except:
            uniq_sorted=sorted(set(vals), reverse=True)
        return delim.join(uniq_sorted)
    elif op=="distinct_only":
        from collections import Counter
        cnt=Counter(vals)
        uniq_only=[v for v in vals if cnt[v]==1]
        return delim.join(uniq_only)
    elif op=="count":
        return str(len(vals))
    elif op=="count_distinct":
        return str(len(set(vals)))
    elif op=="first":
        return vals[0] if vals else ""
    elif op=="last":
        return vals[-1] if vals else ""
    elif op=="sum":
        try:
            s=sum(float(x) for x in vals)
            return format_number(s, prec)
        except:
            return "0"
    elif op=="min":
        try:
            m=min(float(x) for x in vals)
            return format_number(m, prec)
        except:
            return ""
    elif op=="max":
        try:
            m=max(float(x) for x in vals)
            return format_number(m, prec)
        except:
            return ""
    elif op=="absmin":
        try:
            m=min(vals, key=lambda x: abs(float(x)))
            return format_number(float(m), prec)
        except:
            return ""
    elif op=="absmax":
        try:
            m=max(vals, key=lambda x: abs(float(x)))
            return format_number(float(m), prec)
        except:
            return ""
    elif op=="mean":
        try:
            m=sum(float(x) for x in vals)/len(vals) if vals else 0
            return format_number(m, prec)
        except:
            return ""
    elif op=="median":
        try:
            nums=sorted(float(x) for x in vals)
            n=len(nums)
            if n%2==1:
                m=nums[n//2]
            else:
                m=(nums[n//2-1]+nums[n//2])/2
            return format_number(m, prec)
        except:
            return ""
    elif op=="mode":
        try:
            from collections import Counter
            cnt=Counter(vals)
            maxc=max(cnt.values())
            for v in vals:
                if cnt[v]==maxc:
                    return v
        except:
            return ""
    elif op=="antimode":
        try:
            from collections import Counter
            cnt=Counter(vals)
            minc=min(cnt.values())
            for v in vals:
                if cnt[v]==minc:
                    return v
        except:
            return ""
    elif op=="stdev":
        try:
            nums=[float(x) for x in vals]
            if len(nums)<2:
                return format_number(0, prec)
            mean=sum(nums)/len(nums)
            var=sum((x-mean)**2 for x in nums)/len(nums)
            return format_number(math.sqrt(var), prec)
        except:
            return ""
    elif op=="sstdev":
        try:
            nums=[float(x) for x in vals]
            if len(nums)<2:
                return format_number(0, prec)
            mean=sum(nums)/len(nums)
            var=sum((x-mean)**2 for x in nums)/(len(nums)-1) if len(nums)>1 else 0
            return format_number(math.sqrt(var), prec)
        except:
            return ""
    else:
        return ""

def format_number(x, prec=5):
    if abs(x - round(x)) < 1e-9:
        return str(int(round(x)))
    else:
        fmt=f"%.{prec}f" % x
        return fmt
