def hypergeometric_pmf(k, M, n, N):
    # P(X=k) where population M white, n black, draws N, observed k white
    # Use log to avoid overflow: logC via lgamma
    try:
        # Check bounds
        if k<0 or k> M or k> N or N-k > n:
